using System;
using System.Text;
using UnityEngine;
using UnityEngine.InputSystem;
using TMPro;
using LWS.TruckSports;
using DG.Tweening;
namespace LWS.TruckBowling {
public enum BowlingScreen {Setup,Play,Join,Pause,Help,Settings,Scorecard,Handoff,Disconnect,Result,Confirm}
public sealed class BowlingMenus:SportsMenuView {
 public BowlingMatch match;public TMP_InputField[] names;public TMP_Text[] sourceText,levelText;public GameObject[] rows;
 public TMP_Text modeText,countText,sharedText,motionText,setupInfo,joinInfo,helpText,cardTitle,standings,handoffText,resultText,confirmText;
 public RectTransform[] viewRoots;public TMP_Text[] headers,guidance,popups;public TMP_Text[] cells;public TMP_Text[] cardNames;
 public BowlingScreen Screen{get;private set;}public int Revision{get;private set;}bool dirty=true;float nextHUD;int returnPage;string confirmAction;SportsMenuAction[][] actions;Tween celebration;
 public const string Help="THE TRUCK IS THE BALL\nDrive from the grippy approach, cross the foul line, slide into the pins. Crossing the line is expected: there is no foot foul. No throw or shoot button. After commitment, power/braking fade; you get one pass. Poor entries can gutter.\n\nCONTROLS\nSteer left/right; forward accelerates. Reverse first brakes forward motion, then reverses; forward similarly brakes backward motion. Whole pad: left stick / RT / LT. Shared pad: one truck per left/right stick (X steer, Y drive). Keyboard clusters are shown in Setup. Escape / assigned Start pauses; Tab opens the full scorecard.\n\nTEN FRAMES\nStrike: next two deliveries are bonus. Spare: next one. Tenth strike earns two extra deliveries; tenth spare one. X strike, / spare, − miss, … unresolved total. Standing pins stay for the second delivery; strike/frame/bonus rules decide fresh racks. Truck crossing the foul line is legal.\n\nPinfall is counted only after settling: stable lean over 44 degrees, below/outside the deck; a touched or briefly wobbling upright pin does not count. No gutter return or second pass. Pinsetter movement cannot score.\n\nSIMULTANEOUS\n1–4 participants, one lane each. Lanes progress independently. HOT SEAT: 1–8 on one lane, a whole frame per turn, including tenth bonuses. Shared humans confirm the announced handoff; AI proceeds automatically.\n\nNo online play or powerups. Test physical keyboard rollover and controller compatibility. Reduced camera motion is available in Setup.";
 protected override void Start(){base.Start();actions=new SportsMenuAction[pages.Length][];for(int i=0;i<pages.Length;i++)actions[i]=pages[i].GetComponentsInChildren<SportsMenuAction>(true);for(int i=0;i<8;i++){int slot=i;names[i].onEndEdit.AddListener(v=>{match.setup.players[slot].name=string.IsNullOrWhiteSpace(v)?"Player "+(slot+1):v.Trim();match.Save();});}Show(Screen);}
 public void OpenScorecard(){returnPage=(int)BowlingScreen.Pause;Show(BowlingScreen.Scorecard);}
 public void Dirty(){dirty=true;Revision++;}
 public void Show(BowlingScreen screen){Screen=screen;if(celebration!=null&&celebration.IsActive())celebration.Kill();base.Show((int)screen);for(int i=0;i<4;i++)viewRoots[i].gameObject.SetActive(screen==BowlingScreen.Play&&match.lanes[i].cab.view.enabled);if(screen==BowlingScreen.Settings)SettingsText();if(screen==BowlingScreen.Help)helpText.text=Help;dirty=true;Refresh();if(screen==BowlingScreen.Join||screen==BowlingScreen.Disconnect)SelectPrimary();if(screen==BowlingScreen.Result)celebration=resultText.transform.DOScale(1.025f,.4f).SetLoops(4,LoopType.Yoyo).SetUpdate(true);}
 public void SelectPrimary(){if(actions==null||!match.DevicesReady||UnityEngine.EventSystems.EventSystem.current==null)return;string action=Screen==BowlingScreen.Join?"start":"resume";foreach(var item in actions[(int)Screen])if(item.action==action){UnityEngine.EventSystems.EventSystem.current.SetSelectedGameObject(item.gameObject);break;}}
 public void LayoutView(int index,Rect rect,bool enabled){var r=viewRoots[index];r.anchorMin=new Vector2(rect.xMin,rect.yMin);r.anchorMax=new Vector2(rect.xMax,rect.yMax);r.offsetMin=r.offsetMax=Vector2.zero;r.gameObject.SetActive(enabled&&Screen==BowlingScreen.Play);}
 public override void Action(string key){if(match.InMatch&&!match.Finished&&Screen!=BowlingScreen.Play&&Screen!=BowlingScreen.Setup&&!match.MenuConfirm())return;base.Action(key);
  if(key.StartsWith("source")){match.CycleSource(int.Parse(key.Substring(6)));return;}if(key.StartsWith("level")){int i=int.Parse(key.Substring(5));match.setup.players[i].difficulty=(BowlingDifficulty)(((int)match.setup.players[i].difficulty+1)%3);match.Save();return;}if(key.StartsWith("reassign")){match.Unassign(int.Parse(key.Substring(8)));return;}
  switch(key){case "highlights":SportsPrefs.SetInt(BowlingHighlights.Preference,(BowlingHighlights.Policy+1)%3);SportsPrefs.Save();break;case "mode":match.setup.mode=match.setup.mode==BowlingMode.Simultaneous?BowlingMode.HotSeat:BowlingMode.Simultaneous;match.setup.count=Mathf.Min(match.setup.count,match.setup.mode==BowlingMode.HotSeat?8:4);match.Save();break;case "count":match.setup.count=match.setup.count%(match.setup.mode==BowlingMode.HotSeat?8:4)+1;match.Save();break;case "shared":match.setup.sharedHotSeat=!match.setup.sharedHotSeat;match.Save();break;case "motion":match.setup.reducedMotion=!match.setup.reducedMotion;match.Save();break;case "allai":match.PresetAI(match.setup.count,match.setup.mode);match.Save();break;case "start":case "rematch":match.StartMatch();break;case "handoff":match.Handoff();break;case "resume":match.Resume();break;case "scorecard":returnPage=(int)Screen;Show(BowlingScreen.Scorecard);break;case "help":returnPage=(int)Screen;Show(BowlingScreen.Help);break;case "settings":returnPage=(int)Screen;Show(BowlingScreen.Settings);break;case "restart":confirmAction="restart";confirmText.text="Restart all bowling lanes?\nScores reset; participants and controls are retained.";match.Gate();Show(BowlingScreen.Confirm);break;case "front":if(match.InMatch&&!match.Finished){confirmAction="front";confirmText.text="Return to sport selection?\nThis bowling match will be abandoned.";match.Gate();Show(BowlingScreen.Confirm);}else{match.Save();SportsNavigation.FrontEnd();}break;case "yes":if(confirmAction=="restart")match.StartMatch();else{match.Save();SportsNavigation.FrontEnd();}break;case "no":Show(BowlingScreen.Pause);break;case "setup":match.ChangeSetup();break;case "back":if(Screen==BowlingScreen.Join)Show(BowlingScreen.Setup);else Show((BowlingScreen)returnPage);break;}
  dirty=true;Refresh();
 }
 void Refresh(){if(!dirty)return;dirty=false;var s=match.setup;
  if(Screen==BowlingScreen.Setup){foreach(var action in pages[0].GetComponentsInChildren<SportsMenuAction>(true))if(action.action=="highlights"){action.button.buttonText="REPLAYS: "+BowlingHighlights.PolicyName;action.button.UpdateUI();}modeText.text=s.mode==BowlingMode.Simultaneous?"SIMULTANEOUS · ONE PARTICIPANT PER LANE":"HOT SEAT · ONE FRAME PER TURN";countText.text=s.count+" PARTICIPANTS";sharedText.text=s.mode==BowlingMode.HotSeat?(s.sharedHotSeat?"SHARED DEVICES · HANDOFF":"SEPARATE DEVICES"):"EXCLUSIVE INPUT SOURCES";motionText.text=s.reducedMotion?"REDUCED CAMERA MOTION":"STANDARD CAMERA MOTION";for(int i=0;i<8;i++){rows[i].SetActive(i<s.count);var p=s.players[i];names[i].SetTextWithoutNotify(p.name);sourceText[i].text=p.source==BowlingSource.Keyboard?(s.mode==BowlingMode.HotSeat&&s.sharedHotSeat?"SHARED W/A/S/D":p.forward+"/"+p.left+"/"+p.back+"/"+p.right):p.source.ToString().ToUpper();sourceText[i].color=p.color;levelText[i].text=p.source==BowlingSource.AI?p.difficulty.ToString().ToUpper():"HUMAN";levelText[i].transform.parent.gameObject.SetActive(p.source==BowlingSource.AI);}setupInfo.text=s.Validate(out string reason)?"Truck = ball · First-person cab · Drive, do not throw\nControllers: North joins. Whole pad exclusive; left/right sticks separate. No online play.":reason;Focus();}
  if(Screen==BowlingScreen.Join||Screen==BowlingScreen.Disconnect){var b=new StringBuilder("North / Y / Triangle joins an unassigned source.\n\n");for(int i=0;i<s.count;i++){var p=s.players[i];b.Append(i+1).Append(" · ").Append(p.name).Append(" · ").Append(p.source);if(p.Controller)b.Append(match.Ready(i)?" · "+p.pad.displayName+" #"+p.pad.deviceId:" · DISCONNECTED / NOT JOINED");b.Append('\n');}b.Append("\nScores, delivery and pinsetter state are preserved. Reconnect or explicitly reassign. Release controls before confirming.");joinInfo.text=b.ToString();if(actions!=null)foreach(var a in actions[(int)Screen]){if(a.action.StartsWith("reassign")){int slot=int.Parse(a.action.Substring(8));a.gameObject.SetActive(slot<s.count&&s.players[slot].Controller);}if(a.action=="start"||a.action=="resume"){a.button.isInteractable=match.DevicesReady;a.GetComponent<UnityEngine.UI.Button>().interactable=match.DevicesReady;}}Focus();SelectPrimary();}
  if(Screen==BowlingScreen.Handoff){var p=s.players[match.ActiveSlot];handoffText.text="NEXT: "+p.name+"\nFrame "+(p.score.Frame+1)+" · lane 1\n"+DeviceName(match.ActiveSlot)+"\n\nRelease controls, then Enter / owning South / click CONTINUE.\nInactive assigned controllers cannot confirm.";}
  if(Screen==BowlingScreen.Scorecard||Screen==BowlingScreen.Result){cardTitle.text=match.Finished?"FINAL SCORECARD":"SCORECARD · … MEANS PENDING";var b=new StringBuilder();for(int i=0;i<8;i++){cardNames[i].transform.parent.gameObject.SetActive(i<s.count);if(i>=s.count)continue;var p=s.players[i];cardNames[i].text=p.name;cardNames[i].color=p.color;for(int f=0;f<10;f++)cells[i*10+f].text=p.score==null?"·":p.score.Symbols(f)+"\n"+(p.score.Cumulative(f)?.ToString()??"…");b.Append(p.name).Append(": ").Append(p.score==null?"not started":p.score.Finished?p.score.FinalTotal+" FINAL":p.score.ResolvedTotal+" resolved · bonuses/frame pending").Append("\n");}standings.text=(match.Finished?"All totals are final.":"… = unresolved cumulative total. Live totals are not ranked.")+"\nX strike · / spare · − miss · ten frames · truck crossing is legal";}
  if(Screen==BowlingScreen.Result){int best=s.players[match.Winners[0]].score.FinalTotal;var b=new StringBuilder(match.Winners.Length>1?"TIE FOR FIRST · "+best:"WINNER · "+s.players[match.Winners[0]].name+" · "+best);b.Append("\n\nFINAL STANDINGS");int[] order=new int[s.count];for(int i=0;i<s.count;i++)order[i]=i;for(int i=1;i<s.count;i++){int value=order[i],j=i-1;while(j>=0&&s.players[order[j]].score.FinalTotal<s.players[value].score.FinalTotal){order[j+1]=order[j];j--;}order[j+1]=value;}int rank=1;for(int i=0;i<s.count;i++){if(i>0&&s.players[order[i]].score.FinalTotal!=s.players[order[i-1]].score.FinalTotal)rank=i+1;b.Append('\n').Append(rank).Append(". ").Append(s.players[order[i]].name).Append(" · ").Append(s.players[order[i]].score.FinalTotal);}resultText.text=b.ToString();}
 }
 public string DeviceName(int slot){var p=match.setup.players[slot];return p.source==BowlingSource.AI?p.difficulty+" AI":p.source==BowlingSource.Keyboard?match.setup.mode==BowlingMode.HotSeat&&match.setup.sharedHotSeat?"SHARED KEYBOARD W/A/S/D":"KEYBOARD "+p.forward+"/"+p.left+"/"+p.back+"/"+p.right:p.source+" · "+(p.pad==null?"NOT JOINED":p.pad.displayName);}
 protected override void Update(){base.Update();Refresh();if(Time.unscaledTime<nextHUD)return;nextHUD=Time.unscaledTime+.15f;if(Screen!=BowlingScreen.Play)return;for(int i=0;i<4;i++){var lane=match.lanes[i];if(!lane.cab.view.enabled)continue;var p=lane.Owner;var score=p.score;if(score==null)continue;headers[i].text=p.name+"  ·  LANE "+(i+1)+"\n"+(score.Finished?"COMPLETE · "+score.FinalTotal:"FRAME "+(score.Frame+1)+" · DELIVERY "+(score.Ball+1)+" · "+score.ResolvedTotal+" RESOLVED");headers[i].color=p.color;guidance[i].text=lane.Phase==BowlingPhase.Approach?"Line up on the grippy approach · build speed\n"+DeviceName(lane.ownerSlot):lane.Phase==BowlingPhase.Rolling?"COMMITTED · ONE PASS · "+lane.truck.Speed.ToString("F1")+" m/s\nGrip "+Mathf.RoundToInt(lane.truck.Grip*100)+"% · Tab scorecard / Esc pause":lane.Phase==BowlingPhase.Replay?"ACTUAL REPLAY · "+lane.highlights.replay.Speed.ToString("0.##")+"× · CAMERA "+(lane.highlights.replay.Angle+1)+"\nLEFT/RIGHT CAMERA · UP/DOWN SPEED · FWD+BACK / TRIGGER SKIP":lane.Phase==BowlingPhase.Finished?"Lane finished · other lanes continue":"PINSETTER · score locked";popups[i].text=lane.highlights!=null&&lane.highlights.group.alpha>.01f?"":lane.Phase>=BowlingPhase.Popup&&lane.Phase<=BowlingPhase.Setting?lane.Result:"";popups[i].transform.parent.gameObject.SetActive(popups[i].text.Length>0);}}
 void OnDisable(){if(celebration!=null&&celebration.IsActive())celebration.Kill();}
}
}